from pathlib import Path
import json,hashlib,re
p=Path(__file__).resolve().parent
read=lambda n:json.loads((p/n).read_text())
pct=lambda a,b:round((b/a-1)*100,3)
runtime=read('runtime-manifest.json');snapshot=read('bench-runtime-sha256.json')
for row in runtime:assert hashlib.sha256((p/'runtime'/row['path']).read_bytes()).hexdigest()==row['sha256']==snapshot['candidate'][row['path']]
tests=(p/'tests.log').read_text();assert re.search(r'^# pass 1741$',tests,re.M) and re.search(r'^# fail 0$',tests,re.M)
first=[]
for file in ['native-first-load-results.json','native-filled-first-load-results.json']:
 d=read(file);rows=[]
 for row in d['comparisons']:
  a,b=row['baseline'],row['candidate'];rows.append({'scenario':row['scenario'],'baseline':a,'candidate':b,'elapsedPercent':pct(a['medianMs'],b['medianMs']),'peakHeapPercent':pct(a['sampledMaxHeapBytes'],b['sampledMaxHeapBytes']),'heapGrowthPercent':pct(a['medianHeapGrowth'],b['medianHeapGrowth'])})
 first.append({'report':file,'processes':len(d['runs']),'rows':rows})
paired=read('paired-loon-results.json');pairs=[]
for row in paired['comparisons']:
 a,b=row['baseline'],row['candidate'];pairs.append({'kind':row['kind'],'format':row['format'],'baseline':a,'candidate':b,'elapsedPercent':pct(a['elapsedMs'],b['elapsedMs']),'peakHeapPercent':pct(a['sampledMaxHeapBytes'],b['sampledMaxHeapBytes']),'retainedHeapPercent':pct(a['retainedHeapBytes'],b['retainedHeapBytes'])})
jsc=read('mixed-jsc-results.json');jrows=[]
for row in jsc['comparisons']:
 a,b=row['baseline'],row['candidate'];jrows.append({'mode':row['mode'],'scenario':row['scenario'],'baseline':a,'candidate':b,'elapsedPercent':pct(a['milliseconds'],b['milliseconds']),'peakFootprintPercent':pct(a['sampledPeakFootprint'],b['sampledPeakFootprint'])})
mixed=read('mixed-native-churn-results.json');pressure=read('native-pressure-results.json');work=read('work-results.json');features=read('feature-results.json')
summary={'version':'3.1.6','adapter':15,'baselineVersion':'3.1.5','baselineRuntime':'c9eda7c3424f9a446db886cfac08a6e1509c6347','tests':{'passed':1741,'failed':0,'addedSince315':7,'egernYAML':'passed'},'runtime':runtime,'work':work,'firstLoad':first,'pairedLoon':{'processes':len(paired['runs']),'rows':pairs},'jsc':{'processes':len(jsc['runs']),'rows':jrows},'mixedChurn':{'configurations':len(mixed['results']),'responses':sum(r['lyricResponses'] for r in mixed['results']),'warmHTTP':sum(r['warmHTTP'] for r in mixed['results']),'peakHTTP':max(r['maxActiveHTTP'] for r in mixed['results'])},'pressure':{'processes':len(pressure['runs']),'peakLiveInvocations':max(r['peakLiveInvocations'] for r in pressure['runs']),'peakHTTP':max(r['peakHTTP'] for r in pressure['runs']),'admissionTimers':max(r['admissionTimers'] for r in pressure['runs'])},'featureInvocations':features['invocations'],'limitsChanged':False,'scope':'Compiled native host mocks, desktop Node and macOS JSC sampling. Not actual iPhone Spotify UI, all transient allocations, native buffers or VPN acceptance. All final report regressions are retained; synthetic service latency is zero.'}
(p/'validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
lines=['# VerseLyrics 3.1.6 measurements','',summary['scope'],'','Final runtime SHA256 values are checked before and after each measurement step. Both versions use this same fixture codec, cache priming and native host harness; only their actual compiled runtimes differ. Deterministic allocation counters are separate from uninstrumented heap/timing runs.','', '## Actual work reduction','', '| Operation | 3.1.5 | 3.1.6 |','| --- | ---: | ---: |']
a,b=work['results']
for label,old,new in [('128 plain indexed keys: JSON.parse calls',a['indexedRead']['jsonParseCalls'],b['indexedRead']['jsonParseCalls']),('Unused cache: Map containers',a['unusedCache']['mapContainers'],b['unusedCache']['mapContainers']),('Unused cache: WeakMap containers',a['unusedCache']['weakMapContainers'],b['unusedCache']['weakMapContainers'])]:lines.append(f'| {label} | {old} | {new} |')
lines+=['','These are scoped cache-read/bookkeeping counts, not whole-process peaks. Saved values retain validation and escaped keys retain JSON.parse. Track/language fragments are lazily built once per cache view. The rejected range parser is absent; final 600-row byte-view counts remain the same as 3.1.5, with the established 8194-byte scratch limit.','', '## First load: fresh Node processes','', 'Each table uses twelve alternating fresh-process trials per version/scenario, 32 MiB old-space, one script/VM per process. The matrix includes 24/48/120-row ordinary cases and four new 600-row cases covering English, Chinese translation, Chinese preservation and mixed fragments. The filled table starts with 48000-60000 unrelated serialized cache characters. Samples include compiler/code-cache/harness overhead at invocation, HTTP and completion boundaries. Heap growth is sampled peak minus pre-compilation heap, distinct from absolute process heap.','']
for group in first:
 lines+=['### '+group['report'],'',str(group['processes'])+' fresh processes.','', '| Scenario | Baseline ms | Candidate ms | Time change | Absolute sampled heap change | Sampled heap-growth change |','| --- | ---: | ---: | ---: | ---: | ---: |']
 for row in group['rows']:lines.append(f"| {row['scenario']} | {row['baseline']['medianMs']:.3f} | {row['candidate']['medianMs']:.3f} | {row['elapsedPercent']:+.3f}% | {row['peakHeapPercent']:+.3f}% | {row['heapGrowthPercent']:+.3f}% |")
 lines.append('')
lines+=['## Loon repeated playlist comparison','','Five alternating fresh process pairs for each of four cases, 40 processes. Plain: 240 cold songs and 720 HTTP calls. Mixed: 120 song IDs, 240 lyric responses and 120 HTTP calls including a zero-HTTP warm reopen per song. GC runs every six songs. Output hashes and request counts agree.','', '| Case | Format | Baseline ms | Candidate ms | Time change | Sampled heap change | Retained heap change |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
for row in pairs:lines.append(f"| {row['kind']} | {row['format']} | {row['baseline']['elapsedMs']:.3f} | {row['candidate']['elapsedMs']:.3f} | {row['elapsedPercent']:+.3f}% | {row['peakHeapPercent']:+.3f}% | {row['retainedHeapPercent']:+.3f}% |")
lines+=['','The separate native-churn report keeps one functional baseline Loon run and all five candidate clients; the five-pair medians above give the repeated Loon comparison.','', '## macOS JavaScriptCore','', 'Six alternating fresh-process trials per case/version. Cold uses one context; sequence uses 32 fresh contexts without forced GC. The range matrix additionally covers 600 English and Chinese rows, including removal of official translation alternatives without Chinese conversion. All output hashes, bytes and HTTP counts match between versions. Footprints include harness/JIT/allocator overhead.','', '| Mode | Scenario | Baseline ms | Candidate ms | Time change | Peak footprint change |','| --- | --- | ---: | ---: | ---: | ---: |']
for row in jrows:lines.append(f"| {row['mode']} | {row['scenario']} | {row['baseline']['milliseconds']:.3f} | {row['candidate']['milliseconds']:.3f} | {row['elapsedPercent']:+.3f}% | {row['peakFootprintPercent']:+.3f}% |")
lines+=['','## Interpretation and retained behavior','','These changes remove repeated allocations and parsing; they do not establish a universal timing or memory improvement. Ordinary first-load medians remain close to 3.1.5 and include slower cases. Playlist and JSC tables also contain both improvements and regressions. Differences of a few percent in millisecond cold processes should not be treated as reliable real-world network-latency gains. Reduced key parsing and unused containers are deterministic, but absolute process peaks include much larger common runtime costs. The range-parser prototype was rejected after repeatable filled-cache mixed-row heap growth; its reduced view counts are not a shipped improvement.','',f"Loon lyric runtime grows from 90439 to {next(r['bytes'] for r in runtime if r['path']=='Loon/script/SpotifyLyrics.js')} bytes; Loon entry from 30605 to {next(r['bytes'] for r in runtime if r['path']=='Loon/script/SpotifyLyrics.Entry.js')} bytes. Every compiled lyric script remains below 100000 bytes and every entry below 32000 bytes. No cache, body, timeout, request or concurrency limit grows.",'', '- 1741 automated tests pass, 7 new since 3.1.5; native Egern YAML validation passes.','- Twenty client/format/cache-mode mixed playlists produce 4800 native lyric responses. Warm reopen HTTP remains zero, with at most one service request active.','- Sixteen rapid-arrival processes keep at most two live script invocations, one active HTTP request and zero admission timers in the fixture; retired callbacks settle before completion. Admission uses synchronous non-atomic native storage, so these mock counts are not a native concurrency guarantee.','- Sixty compiled native feature invocations preserve missing fallback, static replacement on/off, mixed-English translation, Chinese shape, filler filtering, colors and existing cache bounds.','- Source matching/revision behavior from 3.1.5 remains covered, including the previously supplied static case. No new live catalog-coverage or phone UI claim is made in 3.1.6.','', '## Reproduction','', 'Use README.md commands with an unchanged 3.1.5 stage. run-measurements-316.py records runtime hashes and runs measurements serially. The full JSON reports contain every trial in the final matrix. The matrix includes 600-row first loads and filled caches because they exposed a prototype regression. Pilot reports and pilot-core.diff retain the rejected evidence separately. Final reports use the revised runtime hashes. Pure function instrumentation is in reproduce-316-work.mjs. No third-party lyric text is needed for these fixtures. No desktop result measures iPhone host response buffers or proves VPN stability.']
(p/'MEASUREMENTS.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'tests':1741,'firstLoadProcesses':sum(g['processes'] for g in first),'pairedProcesses':len(paired['runs']),'jscProcesses':len(jsc['runs']),'mixedResponses':summary['mixedChurn']['responses'],'paired':[{k:r[k] for k in ['kind','format','elapsedPercent','peakHeapPercent']} for r in pairs]}))
